import {
  Room,
  RoomEvent,
  Track,
  createLocalAudioTrack,
} from "https://cdn.jsdelivr.net/npm/livekit-client@2/+esm";

const fab = document.getElementById("livekitFab");
const panel = document.getElementById("livekitPanel");
const statusEl = document.getElementById("livekitStatus");
const startBtn = document.getElementById("livekitStart");
const stopBtn = document.getElementById("livekitStop");
const closeBtn = document.getElementById("livekitClose");
const audioBox = document.getElementById("livekitAudio");
const textForm = document.getElementById("livekitTextForm");
const textInput = document.getElementById("livekitTextInput");
const logBox = document.getElementById("livekitLog");

let room = null;
let micTrack = null;

// Text sent in the room is handled by the same `rachel` agent that serves
// voice, so it answers from the agent's own LLM (local Ollama) rather than
// OpenRouter -- which is why text works even with no OpenRouter credits.
function logLine(who, text) {
  if (!logBox) return;
  logBox.hidden = false;
  const row = document.createElement("p");
  row.className = who === "you" ? "lk-you" : "lk-rachel";
  const b = document.createElement("b");
  b.textContent = who === "you" ? "YOU" : "RACHEL";
  const span = document.createElement("span");
  span.textContent = text;
  row.append(b, span);
  logBox.append(row);
  logBox.scrollTop = logBox.scrollHeight;
}

async function sendText(ev) {
  ev.preventDefault();
  const text = (textInput.value || "").trim();
  if (!text) return;
  if (!room) {
    setStatus("Start a live session first so Rachel can hear you.", "error");
    return;
  }
  try {
    // Standard LiveKit chat topic. The rachel agent's AgentSession reads and
    // replies on this topic, which is why text uses the agent's own LLM
    // (local Ollama) and needs no OpenRouter credits.
    await room.localParticipant.sendText(text, { topic: "lk.chat" });
    logLine("you", text);
    textInput.value = "";
  } catch (err) {
    setStatus("Could not send: " + (err.message || err), "error");
  }
}
if (textForm) {
  textForm.addEventListener("submit", sendText);
}

function setStatus(text, mode = "") {
  statusEl.textContent = text;
  statusEl.className = "livekit-status" + (mode ? " " + mode : "");
}

function openPanel() {
  panel.hidden = false;
  fab.hidden = true;
  if (statusEl.dataset.ready !== "1") checkEnabled();
}

function closePanel() {
  if (room) return;
  panel.hidden = true;
  fab.hidden = false;
}

async function checkEnabled() {
  try {
    const res = await fetch(((self.APP_CONFIG&&self.APP_CONFIG.API_BASE)||'') + "/api/livekit/status");
    const data = await res.json();
    if (!data.enabled) {
      setStatus("Live voice is offline right now. Use typed chat.", "error");
      startBtn.disabled = true;
    } else if (data.requiresAuth) {
      // Members-only. Ask for sign-in up front rather than failing on Start.
      const signedIn = await hasSession();
      if (signedIn) {
        setStatus("Ready. Press Start live call.");
      } else {
        setStatus("Sign in to talk live with Rachel.", "");
        startBtn.disabled = false;
        startBtn.dataset.needsLogin = "1";
      }
    } else {
      setStatus("Ready. Press Start live call.");
    }
    statusEl.dataset.ready = "1";
  } catch (err) {
    setStatus("Could not reach the server.", "error");
    statusEl.dataset.ready = "1";
  }
}

/** Server-side session check; the browser never decides this for itself. */
async function hasSession() {
  try {
    const res = await fetch(((self.APP_CONFIG&&self.APP_CONFIG.API_BASE)||'') + "/api/auth/status", { cache: "no-store" });
    const data = await res.json();
    return Boolean(data && data.authenticated);
  } catch (err) {
    return false;
  }
}

/** Show a sign-in prompt instead of a dead Start button. */
function promptSignIn(loginUrl) {
  startBtn.dataset.needsLogin = "1";
  startBtn.disabled = false;
  startBtn.textContent = "Sign in to start";
  statusEl.dataset.ready = "";
  statusEl.dataset.needsLogin = "1";
  statusEl.dataset.loginUrl = loginUrl || "/api/auth/login";
}

async function start() {
  // Button was left in "sign in" mode by checkEnabled(); send them to log in.
  if (startBtn.dataset.needsLogin === "1") {
    const url = statusEl.dataset.loginUrl || "/api/auth/login";
    window.location.href = url;
    return;
  }

  startBtn.disabled = true;
  stopBtn.disabled = false;
  setStatus("Connecting to Rachel…", "connecting");
  try {
    const resp = await fetch("/api/livekit/token", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: "Website visitor" }),
    });
    if (resp.status === 401) {
      // Members-only voice: prompt instead of showing a raw error.
      const err = await resp.json().catch(() => ({}));
      await end(false);
      setStatus("Sign in to talk live with Rachel.", "");
      promptSignIn(err.loginUrl);
      return;
    }
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      setStatus(err.error || "Could not start a live session.", "error");
      startBtn.disabled = false;
      stopBtn.disabled = true;
      return;
    }
    const { url, token } = await resp.json();

    room = new Room();
    room.on(RoomEvent.TrackSubscribed, (track) => {
      if (track.kind === Track.Kind.Audio) {
        audioBox.hidden = false;
        audioBox.replaceChildren();
        audioBox.appendChild(track.attach());
      }
    });
    room.on(RoomEvent.ConnectionStateChanged, (state) => {
      if (state === "connected") setStatus("Connected — Rachel is listening", "connected");
      else if (state === "reconnecting") setStatus("Reconnecting…", "connecting");
      else if (state === "disconnected") setStatus("Disconnected", "");
    });
    room.on(RoomEvent.Disconnected, () => end(true));
    room.on(RoomEvent.MediaDevicesError, (e) =>
      setStatus("Microphone error: " + (e.message || e), "error")
    );

    await room.connect(url, token);
    // Rachel's text replies arrive on the chat topic. This SDK version exposes
    // text via a TextStreamReader rather than RoomEvent.TextReceived. Must run
    // AFTER connect() and must not be awaited, or it deadlocks the connection.
    if (typeof room.localParticipant.streamText === "function") {
      room.localParticipant
        .streamText("lk.chat")
        .then(async (reader) => {
          for await (const chunk of reader) {
            if (chunk && typeof chunk.text === "string" && chunk.text.trim()) {
              logLine("rachel", chunk.text.trim());
            }
          }
        })
        .catch(() => {});
    }
    if (textForm) textForm.hidden = false;
    if (logBox) logBox.hidden = false;
    micTrack = await createLocalAudioTrack({
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true,
    });
    await room.localParticipant.publishTrack(micTrack);
    setStatus("Connected — Rachel is listening", "connected");
  } catch (err) {
    setStatus("Could not connect: " + (err.message || err), "error");
    startBtn.disabled = false;
    stopBtn.disabled = true;
    await end(false);
  }
}

async function end(keepStatus) {
  if (micTrack) {
    try { micTrack.stop(); } catch (_) {}
    micTrack = null;
  }
  if (room) {
    try { await room.disconnect(); } catch (_) {}
    room = null;
  }
  audioBox.hidden = true;
  audioBox.replaceChildren();
  if (textForm) { textForm.hidden = true; textInput.value = ""; }
  if (logBox) { logBox.hidden = true; logBox.replaceChildren(); }
  if (!keepStatus) setStatus("Idle");
  // Clear the sign-in state so the next attempt is a real attempt.
  delete startBtn.dataset.needsLogin;
  startBtn.textContent = "Start live call";
  startBtn.disabled = false;
  stopBtn.disabled = true;
}

fab.addEventListener("click", openPanel);
closeBtn.addEventListener("click", closePanel);
startBtn.addEventListener("click", start);
stopBtn.addEventListener("click", () => end(false));
window.addEventListener("beforeunload", () => {
  if (room) room.disconnect();
});

