import {
  Room,
  RoomEvent,
  Track,
  createLocalAudioTrack,
} from "https://cdn.jsdelivr.net/npm/livekit-client@2/+esm";

// LiveKit project credentials (saved). For a production deployment these
// should live server-side; the token is signed in the browser here so the
// site works on static hosting without a Node backend.
const LIVEKIT_URL = "wss://lexi-claw-lalvr0ll.livekit.cloud";
const LIVEKIT_API_KEY = "APIro5CjUS2dDhe";
const LIVEKIT_API_SECRET = "sKhv8CpBYQJZWPfRS4WMazbQH70wcNufUWDfUB7XlmTB";
const AGENT_NAME = "rachel-voice";

const fab = document.getElementById("livekitFab");
const panel = document.getElementById("livekitPanel");
const statusEl = document.getElementById("livekitStatus");
const startBtn = document.getElementById("livekitStart");
const stopBtn = document.getElementById("livekitStop");
const closeBtn = document.getElementById("livekitClose");
const audioBox = document.getElementById("livekitAudio");

let room = null;
let micTrack = null;

function setStatus(text, mode = "") {
  statusEl.textContent = text;
  statusEl.className = "livekit-status" + (mode ? " " + mode : "");
}

function openPanel() {
  panel.hidden = false;
  fab.hidden = true;
  if (statusEl.dataset.ready !== "1") checkEnabled();
}

function closePanel() {
  if (room) return;
  panel.hidden = true;
  fab.hidden = false;
}

function checkEnabled() {
  setStatus("Ready. Press Start live call.");
  statusEl.dataset.ready = "1";
}

function b64url(bytes) {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function b64urlStr(str) {
  return b64url(new TextEncoder().encode(str));
}
function randHex(n) {
  const a = new Uint8Array(n);
  crypto.getRandomValues(a);
  return [...a].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// Sign a LiveKit access token (HS256 JWT) entirely in the browser.
async function makeToken(roomName, identity, name) {
  const header = { alg: "HS256", typ: "JWT" };
  const now = Math.floor(Date.now() / 1000);
  const payload = {
    iss: LIVEKIT_API_KEY,
    sub: identity,
    name,
    iat: now,
    nbf: now,
    exp: now + 3600,
    video: {
      room: roomName,
      roomJoin: true,
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
      roomConfig: { agents: [{ agentName: AGENT_NAME }] },
    },
  };
  const signingInput = b64urlStr(JSON.stringify(header)) + "." + b64urlStr(JSON.stringify(payload));
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(LIVEKIT_API_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(signingInput));
  return signingInput + "." + b64url(new Uint8Array(sig));
}

async function start() {
  startBtn.disabled = true;
  stopBtn.disabled = false;
  setStatus("Connecting to Rachel…", "connecting");
  try {
    const roomName = "rachel-site-" + randHex(8);
    const identity = "visitor-" + randHex(6);
    const token = await makeToken(roomName, identity, "Website visitor");

    room = new Room();
    room.on(RoomEvent.TrackSubscribed, (track) => {
      if (track.kind === Track.Kind.Audio) {
        audioBox.hidden = false;
        audioBox.replaceChildren();
        audioBox.appendChild(track.attach());
      }
    });
    room.on(RoomEvent.ConnectionStateChanged, (state) => {
      if (state === "connected") setStatus("Connected — Rachel is listening", "connected");
      else if (state === "reconnecting") setStatus("Reconnecting…", "connecting");
      else if (state === "disconnected") setStatus("Disconnected", "");
    });
    room.on(RoomEvent.Disconnected, () => end(true));
    room.on(RoomEvent.MediaDevicesError, (e) =>
      setStatus("Microphone error: " + (e.message || e), "error")
    );

    await room.connect(LIVEKIT_URL, token);
    micTrack = await createLocalAudioTrack({
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true,
    });
    await room.localParticipant.publishTrack(micTrack);
    setStatus("Connected — Rachel is listening", "connected");
  } catch (err) {
    setStatus("Could not connect: " + (err.message || err) + " Call or text Rachel at +1 (484) 317-0032.", "error");
    startBtn.disabled = false;
    stopBtn.disabled = true;
    await end(false);
  }
}

async function end(keepStatus) {
  if (micTrack) {
    try { micTrack.stop(); } catch (_) {}
    micTrack = null;
  }
  if (room) {
    try { await room.disconnect(); } catch (_) {}
    room = null;
  }
  audioBox.hidden = true;
  audioBox.replaceChildren();
  if (!keepStatus) setStatus("Idle");
  startBtn.disabled = false;
  stopBtn.disabled = true;
}

