api/stripe-pk.js:
// Serves the Stripe publishable key for the embedded Checkout form.
// Publishable keys are public by design (pk_...); never expose the secret key.
const ALLOWED = /^pk_(test|live)_/;

async function handler(req, res) {
  const key = process.env.STRIPE_PUBLISHABLE_KEY || "";
  if (!key || !ALLOWED.test(key)) {
    return res.status(503).json({ error: "Publishable key not configured." });
  }
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Cache-Control", "public, max-age=300");
  return res.status(200).json({ publishableKey: key });
}

module.exports = handler;

api/_workos.js:
// WorkOS AuthKit helpers for Vercel Functions.
//
// AuthKit is the single source of truth for "who is signed in". This is a port
// of the Express implementation in backend/server.js so the Vercel deployment
// and the k8s deployment enforce identical rules.
//
// Session security:
//   - the sealed session lives in an HttpOnly, Secure, SameSite=Lax cookie, so
//     page JavaScript can never read or forge it
//   - the session is sealed by WorkOS with WORKOS_COOKIE_PASSWORD, so it cannot
//     be forged client-side
//   - every check is verified server-side; the browser is never trusted
//
// _auth.js remains the magic-link/Neon session helper. Nothing here depends on
// it, so the two auth stacks cannot interfere.

const { WorkOS } = require("@workos-inc/node");

const SESSION_COOKIE = "wos-session";
const MAX_AGE_SECONDS = 60 * 60 * 24 * 30; // 30 days

function env(name) {
  const v = process.env[name];
  return typeof v === "string" && v.trim() ? v.trim() : "";
}

/** True when AuthKit has everything it needs to authenticate anyone. */
function isConfigured() {
  return Boolean(
    env("WORKOS_API_KEY") && env("WORKOS_CLIENT_ID") && env("WORKOS_COOKIE_PASSWORD").length >= 32
  );
}

function client() {
  if (!isConfigured()) return null;
  return new WorkOS(env("WORKOS_API_KEY"), { clientId: env("WORKOS_CLIENT_ID") });
}

function publicUrl() {
  const configured = env("RACHEL_PUBLIC_URL");
  if (configured) return configured.replace(/\/$/, "");
  return "https://rachelfindsdealz.site";
}

/**
 * Where AuthKit sends the browser back to. Must be registered in the WorkOS
 * dashboard. Falls back to the deployed origin so a stale localhost value
 * cannot silently send users off-site.
 */
function redirectUri() {
  const configured = env("WORKOS_REDIRECT_URI");
  if (configured) return configured;
  return publicUrl() + "/api/auth/callback";
}

function parseCookies(req) {
  const header = (req && req.headers && req.headers.cookie) || "";
  const out = {};
  for (const part of header.split(";")) {
    const idx = part.indexOf("=");
    if (idx < 0) continue;
    out[part.slice(0, idx).trim()] = part.slice(idx + 1).trim();
  }
  return out;
}

function readSession(req) {
  return parseCookies(req)[SESSION_COOKIE] || "";
}

function sessionCookie(sealedSession) {
  return [
    `${SESSION_COOKIE}=${sealedSession}`,
    "Path=/",
    "HttpOnly",
    "SameSite=Lax",
    `Max-Age=${MAX_AGE_SECONDS}`,
    "Secure",
  ].join("; ");
}

function clearCookie() {
  return `${SESSION_COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Secure`;
}

/**
 * Resolve the caller to a WorkOS user, or null.
 *
 * Tries the cookie as-is, then one refresh, re-sealing the cookie so a rolling
 * session keeps the user signed in. Every failure path resolves to null rather
 * than throwing, so callers have a single "am I signed in?" check.
 */
async function currentUser(req, res) {
  const workos = client();
  if (!workos) return null;

  const sessionData = readSession(req);
  if (!sessionData) return null;

  let session;
  try {
    session = workos.userManagement.loadSealedSession({
      sessionData,
      cookiePassword: env("WORKOS_COOKIE_PASSWORD"),
    });
  } catch (e) {
    console.error("authkit: could not unseal session:", e && e.message);
    return null;
  }

  try {
    const { authenticated, user } = await session.authenticate();
    if (authenticated) return user;
  } catch (e) {
    console.error("authkit: authenticate failed:", e && e.message);
    return null;
  }

  // Not authenticated: the sealed session may simply have rolled over.
  if (!res) return null;
  try {
    const refreshResult = await session.refresh();
    if (!refreshResult.authenticated) {
      res.setHeader("Set-Cookie", clearCookie());
      return null;
    }
    res.setHeader("Set-Cookie", sessionCookie(refreshResult.sealedSession));
    return refreshResult.user || null;
  } catch (e) {
    console.error("authkit: refresh failed:", e && e.message);
    res.setHeader("Set-Cookie", clearCookie());
    return null;
  }
}

/** A stable, non-guessable identity for a signed-in member. */
function memberIdentity(user) {
  return "member-" + String(user && (user.id || user.email)).replace(/[^a-zA-Z0-9_-]/g, "-");
}

/** Standard headers for an unauthenticated JSON response. */
function noStore(res) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
  res.setHeader("Cache-Control", "no-store");
}

module.exports = {
  SESSION_COOKIE,
  clearCookie,
  client,
  currentUser,
  env,
  isConfigured,
  memberIdentity,
  noStore,
  publicUrl,
  readSession,
  redirectUri,
  sessionCookie,
};

