const withCors = require("./_cors");
module.exports = withCors(async function handler(req, res) {
  if (req.method !== "POST") return res.status(405).json({ error: "Use POST" });

  let body = req.body;
  if (typeof body === "string") {
    try { body = JSON.parse(body || "{}"); } catch { body = {}; }
  }
  body = body || {};

  const message = (body.message || "").toString().trim();
  if (!message) return res.status(400).json({ error: "Message is required." });

  try {
    const answer = await runChat(message);
    if (!answer) throw new Error("The coaching service returned no answer.");
    res.status(200).json({ answer });
  } catch (e) {
    res.status(502).json({ error: e.message || "Chat failed." });
  }
});

const SYSTEM = [
  "You are Rachel, an AI coach for a 30-day assignment-of-contract mission with a $3,500 goal.",
  "You help real-estate investors understand and execute assignments of contract (wholesaling):",
  "getting a property under an assignable contract and assigning it to an end buyer for an assignment fee,",
  "without ever taking ownership. Be concise, accurate, and practical. Use plain language.",
  "When a figure or next step depends on the user's specific deal, ask for the missing detail",
  "(address/area, contract price, ARV, repair estimate, timeline, buyer criteria) before giving numbers.",
  "Recommend a qualified local real-estate attorney or title/escrow company for contract review and",
  "state-specific rules. Never fabricate comps, prices, or legal requirements.",
].join(" ");

// Fallback order, most capable first.
//
// Verified empirically against the live account: every ":free" id returns 404
// ("no endpoints available matching your guardrail restrictions") because
// /api/v1/endpoints/zdr lists ZDR endpoints ONLY for DeepInfra/Novita/Azure/
// Google, while this account pins allowed-providers to nvidia/openai/tencent.
// The Tencent ids below ARE ZDR-eligible and reachable, but they are PAID and
// return 402 while the account has no credits.
//
// So there is no zero-cost option under the current account policy. Chat works
// as soon as EITHER credits are added OR the provider pin is relaxed to
// include Novita/DeepInfra. Override with OPENROUTER_MODEL.
const DEFAULT_MODELS = [
  "tencent/hy3",
  "tencent/hy-mt2-30b-a3b",
  "tencent/hy-mt2-7b",
  "tencent/hy4-preview",
  "tencent/hy-mt2-1.8b",
];

async function runChat(message) {
  // Proxy to a self-hosted Rachel backend (e.g. Docker + Ollama on this box).
  if (process.env.RACHEL_LLM_URL) {
    const r = await fetch(process.env.RACHEL_LLM_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message }),
    });
    if (!r.ok) throw new Error("LLM proxy " + r.status);
    const d = await r.json();
    return (d.answer || d.reply || "").toString().trim();
  }

  // Public LLM via OpenRouter (works from serverless / Vercel).
  if (process.env.OPENROUTER_API_KEY) {
    const candidates = process.env.OPENROUTER_MODEL
      ? process.env.OPENROUTER_MODEL.split(",").map((m) => m.trim()).filter(Boolean)
      : DEFAULT_MODELS;

    let lastErr = "unknown";
    for (const model of candidates) {
      try {
        const r = await fetch("https://openrouter.ai/api/v1/chat/completions", {
          method: "POST",
          headers: {
            Authorization: "Bearer " + process.env.OPENROUTER_API_KEY,
            "Content-Type": "application/json",
            "HTTP-Referer": process.env.RACHEL_PUBLIC_URL || "https://rachelfindsdealz.site",
            "X-Title": "Rachel Assignment Coach",
          },
          body: JSON.stringify({
            model,
            // Never send user messages to an endpoint that retains data. This
            // also prevents a ZDR-enabled account from 404-ing with
            // "0 endpoints available matching your guardrail restrictions".
            provider: { zdr: true },
            messages: [
              { role: "system", content: SYSTEM },
              { role: "user", content: message },
            ],
          }),
        });

        if (!r.ok) {
          const t = await r.text();
          lastErr = model + ": OpenRouter " + r.status + " " + t.slice(0, 300);
          console.error("[chat] upstream error ->", lastErr);
          continue; // try the next model
        }

        const d = await r.json();
        const content =
          d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content;
        if (content && content.trim()) return content.trim();
        lastErr = model + ": empty completion";
      } catch (e) {
        lastErr = model + ": " + (e.message || e);
      }
    }
    throw new Error(
      "All chat models failed. Last error -> " +
        lastErr +
        ". This usually means the OpenRouter account has no credits, or its" +
        " provider/ZDR policy blocks every configured model. Check credits at" +
        " https://openrouter.ai/settings/credits or set OPENROUTER_MODEL."
    );
  }

  // Self-hosted / local OpenAI-compatible endpoint (LM Studio, OpenWebUI, etc.).
  const url = process.env.OPENWEBUI_URL;
  if (url) {
    const r = await fetch(url.replace(/\/$/, "") + "/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + (process.env.OPENWEBUI_API_KEY || "sk-noauth"),
      },
      body: JSON.stringify({
        model: process.env.OPENWEBUI_MODEL || "local-model",
        messages: [
          { role: "system", content: SYSTEM },
          { role: "user", content: message },
        ],
      }),
    });
    if (!r.ok) {
      const t = await r.text();
      throw new Error("LLM " + r.status + ": " + t.slice(0, 300));
    }
    const d = await r.json();
    return d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content;
  }

  throw new Error(
    "No chat backend configured. Set OPENROUTER_API_KEY (public) for production, or OPENWEBUI_URL for self-hosted."
  );
}

