const withCors = require("./_cors");
const workos = require("./_workos");

// Mirrors DEFAULT_MODELS in chat.js so a broken LLM config is visible on the
// health check instead of only surfacing as a 502 to end users.
const CHAT_MODELS = [
  "tencent/hy3",
  "tencent/hy-mt2-30b-a3b",
  "tencent/hy-mt2-7b",
  "tencent/hy4-preview",
  "tencent/hy-mt2-1.8b",
];

module.exports = async function handler(_req, res) {
  const models = process.env.OPENROUTER_MODEL
    ? process.env.OPENROUTER_MODEL.split(",").map((m) => m.trim()).filter(Boolean)
    : CHAT_MODELS;

  res.status(200).json({
    ok: true,
    livekit: Boolean(
      process.env.LIVEKIT_API_KEY && process.env.LIVEKIT_API_SECRET && process.env.LIVEKIT_URL
    ),
    // True only when a backend credential exists. This is NOT proof chat works:
    // OpenRouter rejects calls with 402 when the account has no credits, so
    // consumers must treat a successful /api/chat as the only real signal.
    chat: Boolean(process.env.OPENROUTER_API_KEY || process.env.OPENWEBUI_URL),
    chatConfigured: Boolean(process.env.OPENROUTER_API_KEY || process.env.OPENWEBUI_URL),
    // Explicit config surface: confirms which model ids /api/chat will try,
    // and that at least one backend credential exists.
    chatModels: models,
    // AuthKit drives sign-in AND the live-voice gate. If this is false, voice
    // fails closed with 503 rather than falling back to open access.
    auth: {
      provider: "workos-authkit",
      configured: workos.isConfigured(),
      // Guard against a leftover localhost redirect silently breaking sign-in.
      redirectUri: workos.redirectUri(),
      voiceRequiresAuth: true,
    },
  });
};

module.exports = withCors(module.exports);

