const workos = require("./_workos");
// Server-side Stripe Checkout for the 30-Day Challenge tiers.
// Secret key is read ONLY from Vercel env (STRIPE_SECRET_KEY) — never sent to the browser.
const PRICES = {
  starter: "STRIPE_PRICE_STARTER",
  pro: "STRIPE_PRICE_PRO",
  platinum: "STRIPE_PRICE_PLATINUM",
};

async function handler(req, res) {
  try {
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type");
    if (req.method === "OPTIONS") return res.status(204).end();
    if (req.method !== "POST") return res.status(405).json({ error: "Use POST" });

    let body = req.body;
    if (typeof body === "string") {
      try { body = JSON.parse(body || "{}"); } catch { body = {}; }
    }
    body = body || {};

    const tier = String(body.tier || "").toLowerCase();
    const priceEnv = PRICES[tier];
    if (!priceEnv) {
      return res.status(400).json({ error: 'Unknown tier. Use starter, pro, or platinum.' });
    }

    const secretKey = process.env.STRIPE_SECRET_KEY;
    if (!secretKey) {
      return res.status(503).json({ error: "Stripe is not configured on the server yet." });
    }

    const priceId = process.env[priceEnv];
    if (!priceId) {
      return res.status(503).json({ error: "No Stripe price configured for this tier yet." });
    }

    const Stripe = require("stripe");
    const stripe = new Stripe(secretKey, { apiVersion: "2026-03-25.dahlia" });
    const origin = workos.publicUrl();
    const embedded = body.ui === "embedded";

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      line_items: [{ price: priceId, quantity: 1 }],
      payment_method_types: ["card"],
      ...(embedded
        ? {
            ui_mode: "embedded",
            return_url: `${origin}/challenge.html?paid=1&tier=${tier}`,
          }
        : {
            success_url: `${origin}/challenge.html?paid=1&tier=${tier}`,
            cancel_url: `${origin}/challenge.html?pricing=1`,
          }),
      allow_promotion_codes: true,
      metadata: { tier, plan: tier },
    });

    if (embedded) {
      return res.status(200).json({ client_secret: session.client_secret, mode: session.mode, tier });
    }
    return res.status(200).json({ url: session.url });
  } catch (e) {
    console.error("checkout error:", e && e.message);
    return res.status(500).json({ error: "Could not start checkout. Please try again later." });
  }
}

module.exports = handler;

