    if (req.method === "OPTIONS") return res.status(204).end();
    return handler(req, res);
  };
};

api/_auth.js:
// Magic-link authentication helpers.
//
// Security posture follows docs/SELF_SERVE_BILLING_ARCHITECTURE.md:
//   - login tokens are cryptographically random, stored only as a SHA-256
//     hash, short-lived, and single-use
//   - rate limits are keyed by normalized email AND client IP
//   - the request endpoint never reveals whether an account exists
//   - sessions use signed HttpOnly, Secure, SameSite=Lax cookies
//   - no password is ever accepted, stored, or compared
//
// Secrets are read from the environment only. Nothing here logs an email
// address, token, or cookie value.

const crypto = require("crypto");

const TOKEN_TTL_MINUTES = 15;
const SESSION_TTL_DAYS = 30;

// Window and caps for the request-login rate limit.
const RATE_WINDOW_MINUTES = 15;
const RATE_MAX_PER_EMAIL = 5;
const RATE_MAX_PER_IP = 20;

const COOKIE_NAME = "rachel_session";

function env(name) {
  const v = process.env[name];
  return typeof v === "string" && v.trim() ? v.trim() : "";
}

/**
 * Pooled Neon connection. Throws if DATABASE_URL is unset.
 *
 * @neondatabase/serverless takes a config object, not a URL string, so the
 * connection string is parsed here. Vercel supplies DATABASE_URL as a string,
 * so passing it straight through would fail at runtime.
 */
function pool() {
  const url = env("DATABASE_URL");
  if (!url) throw new Error("DATABASE_URL is not configured");

  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error("DATABASE_URL is not a valid connection string");
  }
  const database = parsed.pathname.replace(/^\//, "");
  if (!database) throw new Error("DATABASE_URL is missing a database name");

  const { Pool } = require("@neondatabase/serverless");
  return new Pool({
    host: parsed.hostname,
    port: Number(parsed.port || 5432),
    user: parsed.username,
    password: parsed.password,
    database,
    // Serverless driver talks over WebSocket/HTTP, so TLS is implicit.
    ssl: true,
  });
}

/**
 * Run a parameterized query and return the rows array.
 *
 * @neondatabase/serverless resolves to a full result object
 * ({ rows, rowCount, fields, ... }), not a bare array. Every caller here wants
 * just the rows, so unwrap in one place instead of at each call site.
 */
async function query(neon, text, params = []) {
  const result = await neon.query(text, params);
  if (Array.isArray(result)) return result;
  return result && Array.isArray(result.rows) ? result.rows : [];
}

function sha256(value) {
  return crypto.createHash("sha256").update(value, "utf8").digest("hex");
}

/** Lowercase + trim, so "A@B.com " and "a@b.com" are one member. */
function normalizeEmail(email) {
  return String(email || "").trim().toLowerCase();
}

/** Conservative shape check; deliberately not a full RFC 5322 parser. */
function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) && email.length <= 254;
}

function sessionSecret() {
  const secret = env("SESSION_SECRET");
  if (!secret || secret.length < 32) {
    throw new Error("SESSION_SECRET is not configured or too short (need 32+ chars)");
  }
  return secret;
}

function sign(value) {
  return crypto.createHmac("sha256", sessionSecret()).update(value).digest("base64url");
}

/** 256 bits of entropy, URL-safe. Only the hash of this is ever stored. */
function generateToken() {
  return crypto.randomBytes(32).toString("base64url");
}

/** Constant-time comparison that tolerates differing lengths. */
function safeEqual(a, b) {
  const ab = Buffer.from(String(a));
  const bb = Buffer.from(String(b));
  if (ab.length !== bb.length) return false;
  return crypto.timingSafeEqual(ab, bb);
}

function clientIp(req) {
  const fwd = req.headers["x-forwarded-for"];
  if (typeof fwd === "string" && fwd) return fwd.split(",")[0].trim();
  return req.socket && req.socket.remoteAddress ? req.socket.remoteAddress : "unknown";
}

function userAgent(req) {
  const ua = req.headers["user-agent"];
  return typeof ua === "string" ? ua.slice(0, 255) : null;
}

/** Absolute base URL from server config only, never from request input. */
function publicUrl() {
  const configured = env("RACHEL_PUBLIC_URL");
  if (configured) return configured.replace(/\/$/, "");
  return "https://rachelfindsdealz.site";
}

/**
 * Fixed-window rate limit. Returns true when the action is allowed.
 * Two independent buckets: per-email and per-IP.
 */
async function checkRateLimit(neon, emailNormalized, ip) {
  const windowMs = RATE_WINDOW_MINUTES * 60 * 1000;
  const buckets = [
    { key: `email:${emailNormalized}`, max: RATE_MAX_PER_EMAIL },
    { key: `ip:${ip}`, max: RATE_MAX_PER_IP },
  ];

  for (const { key, max } of buckets) {
    const rows = await query(
      neon,
      `INSERT INTO auth_rate_limits (bucket, count, window_start)
       VALUES ($1, 1, now())
       ON CONFLICT (bucket) DO UPDATE
         SET count = CASE
                        WHEN auth_rate_limits.window_start
                             < now() - ($2 || ' milliseconds')::interval
                        THEN 1
                        ELSE auth_rate_limits.count + 1
                      END,
             window_start = CASE
                        WHEN auth_rate_limits.window_start
                             < now() - ($2 || ' milliseconds')::interval
                        THEN now()
                        ELSE auth_rate_limits.window_start
                      END
       RETURNING count`,
      [key, String(windowMs)]
    );
    if (rows.length && rows[0].count > max) return false;
  }
  return true;
}

/** Insert a single-use login token, returning the raw token for emailing. */
async function createLoginToken(neon, memberId, ip, ua) {
  const token = generateToken();
  await query(
    neon,
    `INSERT INTO login_tokens (member_id, token_hash, expires_at, request_ip, user_agent)
     VALUES ($1, $2, now() + ($3 || ' minutes')::interval, $4, $5)`,
    [memberId, sha256(token), String(TOKEN_TTL_MINUTES), ip, ua]
  );
  return token;
}

/**
 * Redeem a token. Returns the member id or null.
 *
 * Single-use and expiry are enforced inside the UPDATE, so two concurrent
 * redemptions of the same token cannot both succeed.
 */
async function redeemLoginToken(neon, token) {
  const rows = await query(
    neon,
    `UPDATE login_tokens
        SET used_at = now()
      WHERE token_hash = $1
        AND used_at IS NULL
        AND expires_at > now()
      RETURNING member_id`,
    [sha256(token)]
  );
  return rows.length ? rows[0].member_id : null;
}

async function createSession(neon, memberId, ip, ua) {
  const id = crypto.randomBytes(32).toString("base64url");
  await query(
    neon,
    `INSERT INTO sessions (member_id, session_hash, expires_at, user_agent, request_ip)
     VALUES ($1, $2, now() + ($3 || ' days')::interval, $4, $5)`,
    [memberId, sha256(id), String(SESSION_TTL_DAYS), ua, ip]
  );
  return id;
}

function sessionCookie(sessionId, maxAgeSeconds) {
  return [
    `${COOKIE_NAME}=${sessionId}.${sign(sessionId)}`,
    "Path=/",
    "HttpOnly",
    "SameSite=Lax",
    `Max-Age=${maxAgeSeconds}`,
    "Secure",
  ].join("; ");
}

function clearCookie() {
  return `${COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Secure`;
}

function parseCookies(req) {
  const header = req.headers.cookie || "";
  const out = {};
  for (const part of header.split(";")) {
    const idx = part.indexOf("=");
    if (idx < 0) continue;
    out[part.slice(0, idx).trim()] = part.slice(idx + 1).trim();
  }
  return out;
}

/** Resolve the signed cookie to a member id, or null. Checks HMAC then DB row. */
async function currentMemberId(neon, req) {
  const raw = parseCookies(req)[COOKIE_NAME];
  if (!raw) return null;
  const dot = raw.lastIndexOf(".");
  if (dot <= 0) return null;
  const id = raw.slice(0, dot);
  if (!safeEqual(sign(id), raw.slice(dot + 1))) return null;

  const rows = await query(
    neon,
    `SELECT s.member_id
       FROM sessions s
      WHERE s.session_hash = $1
        AND s.revoked_at IS NULL
        AND s.expires_at > now()
      LIMIT 1`,
    [sha256(id)]
  );
  return rows.length ? rows[0].member_id : null;
}

async function revokeSession(neon, req) {
  const raw = parseCookies(req)[COOKIE_NAME];
  if (!raw) return;
  const dot = raw.lastIndexOf(".");
  if (dot <= 0) return;
  await query(
    neon,
    `UPDATE sessions SET revoked_at = now()
      WHERE session_hash = $1 AND revoked_at IS NULL`,
    [sha256(raw.slice(0, dot))]
  );
}

module.exports = {
  COOKIE_NAME,
  RATE_MAX_PER_EMAIL,
  RATE_MAX_PER_IP,
  SESSION_TTL_DAYS,
  TOKEN_TTL_MINUTES,
  checkRateLimit,
  clearCookie,
  clientIp,
  createLoginToken,
  createSession,
  currentMemberId,
  env,
  generateToken,
  isValidEmail,
  normalizeEmail,
  pool,
  publicUrl,
  query,
  redeemLoginToken,
  revokeSession,
  safeEqual,
  sessionCookie,
  sha256,
  sign,
  userAgent,
};

