// GET /api/auth/status
//
// Reports whether the caller holds a valid AuthKit session, plus the minimal
// profile fields the account page renders.
//
// This is the server-side authority: the browser's own view of "am I signed
// in?" is never trusted. Only the fields the UI actually displays are returned,
// so no unexpected identity data is exposed to the client.

const workos = require("../_workos");

module.exports = async function handler(req, res) {
  workos.noStore(res);
  if (req.method === "OPTIONS") return res.status(204).end();
  if (req.method !== "GET") return res.status(405).json({ error: "Use GET" });

  if (!workos.isConfigured()) {
    return res.status(503).json({ authenticated: false, configured: false });
  }

  const user = await workos.currentUser(req, res);
  if (!user) return res.status(200).json({ authenticated: false, user: null });

  return res.status(200).json({
    authenticated: true,
    user: {
      email: user.email || null,
      firstName: user.firstName || null,
      lastName: user.lastName || null,
      createdAt: user.createdAt || null,
      updatedAt: user.updatedAt || null,
      lastActiveAt: user.lastActiveAt || null,
    },
  });
};

api/auth/login.js:
// GET /api/auth/login
//
// Initiates the AuthKit flow. The browser is handed straight to WorkOS hosted
// login, which handles email magic links, Google, and any other enabled
// provider. No credentials are ever handled here.

const workos = require("../_workos");

module.exports = async function handler(req, res) {
  if (req.method === "OPTIONS") return res.status(204).end();

  const client = workos.client();
  if (!client) {
    return res
      .status(503)
      .json({ error: "Sign-in is not available right now.", code: "auth_unconfigured" });
  }

  let authorizationUrl;
  try {
    authorizationUrl = client.userManagement.getAuthorizationUrl({
      provider: "authkit",
      redirectUri: workos.redirectUri(),
      clientId: workos.env("WORKOS_CLIENT_ID"),
    });
  } catch (e) {
    console.error("authkit: getAuthorizationUrl failed:", e && e.message);
    return res.status(500).json({ error: "Could not start sign-in." });
  }

  // AuthKit redirects the browser, so this is a real 302 rather than JSON.
  res.setHeader("Cache-Control", "no-store");
  res.status(302);
  res.setHeader("Location", authorizationUrl);
  res.end();
};

api/auth/callback.js:
// GET /api/auth/callback
//
// OAuth/AuthKit redirect target. Exchanges the authorization code for a sealed
// session and stores it in an HttpOnly cookie. This must match the Redirect URI
// registered in the WorkOS dashboard.
//
// The sealed session is set by WorkOS and sealed with WORKOS_COOKIE_PASSWORD,
// so it cannot be forged client-side. No token is ever exposed to JavaScript.

const workos = require("../_workos");

module.exports = async function handler(req, res) {
  if (req.method === "OPTIONS") return res.status(204).end();

  const client = workos.client();
  if (!client) return res.status(503).send("Sign-in is not available right now.");

  const { code, error: oauthError } = req.query || {};

  // WorkOS sends ?error=... when the user declines or the request is denied.
  if (oauthError) {
    console.error("authkit: authorization returned", oauthError);
    return res.redirect(302, workos.publicUrl() + "/login.html?error=denied");
  }
  if (!code) {
    return res.status(400).send("No authorization code provided.");
  }

  try {
    const authenticateResponse = await client.userManagement.authenticateWithCode({
      clientId: workos.env("WORKOS_CLIENT_ID"),
      code: String(code),
      session: {
        sealSession: true,
        cookiePassword: workos.env("WORKOS_COOKIE_PASSWORD"),
      },
    });

    res.setHeader("Set-Cookie", workos.sessionCookie(authenticateResponse.sealedSession));
    res.setHeader("Cache-Control", "no-store");
    return res.redirect(302, workos.publicUrl() + "/account.html");
  } catch (e) {
    console.error("authkit: callback exchange failed:", e && e.message);
    return res.redirect(302, workos.publicUrl() + "/login.html?error=invalid");
  }
};

api/auth/logout.js:
// POST /api/auth/logout
//
// Ends the session locally and asks AuthKit to invalidate it upstream, so the
// session cannot be reused even if the cookie were somehow replayed.
//
// Replaces the magic-link version, which revoked a Neon session row. AuthKit
// sessions are sealed by WorkOS rather than stored by us, so there is no local
// row to delete — the cookie is cleared and AuthKit does the revocation.
//
// The session cookie is SameSite=Lax, which already blocks cross-site POST
// delivery of that cookie. The Origin check is defence in depth: a logout is a
// state change, so a mismatched Origin is refused rather than trusted.

const workos = require("../_workos");

function sameOrigin(req) {
  const origin = req.headers && req.headers.origin;
  if (!origin) return true; // same-origin form posts may omit Origin
  try {
    return new URL(origin).host === (req.headers && req.headers.host);
  } catch {
    return false;
  }
}

async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
  res.setHeader("Cache-Control", "no-store");
  if (req.method === "OPTIONS") return res.status(204).end();
  if (req.method !== "POST") return res.status(405).json({ error: "Use POST" });

  if (!sameOrigin(req)) {
    return res.status(403).json({ error: "Cross-origin sign-out refused." });
  }

  const client = workos.client();
  const sessionData = workos.readSession(req);
  let redirectTo = workos.publicUrl() + "/";

  if (client && sessionData) {
    try {
      const session = client.userManagement.loadSealedSession({
        sessionData,
        cookiePassword: workos.env("WORKOS_COOKIE_PASSWORD"),
      });
      redirectTo = await session.getLogoutUrl();
    } catch (e) {
      console.error("authkit: getLogoutUrl failed:", e && e.message);
      // Fall through: still clear the local cookie below.
    }
  }

  res.setHeader("Set-Cookie", workos.clearCookie());
  return res.status(200).json({ ok: true, redirect: redirectTo });
}

module.exports = handler;

api/livekit/status.js:
// Reports whether live voice is available.
//
// `requiresAuth` tells the client to prompt for sign-in before attempting a
// call, so a member-only rollout does not look like a broken button.
const withCors = require("../_cors");
const workos = require("../_workos");

module.exports = async function handler(req, res) {
  const enabled = Boolean(
    process.env.LIVEKIT_API_KEY &&
    process.env.LIVEKIT_API_SECRET &&
    process.env.LIVEKIT_URL
  );

  const requiresAuth = true;
  // AuthKit, not the legacy magic-link env vars, gates voice now.
  const authReady = workos.isConfigured();

  res.status(200).json({
    enabled,
    requiresAuth,
    // Whether AuthKit is configured at all. This is NOT the caller's session —
    // a client must never treat it as "I am signed in". Use /api/auth/status
    // for that. Kept under an honest name so the two cannot be confused.
    authConfigured: authReady,
    loginUrl: `${workos.publicUrl()}/api/auth/login`,
  });
};

module.exports = withCors(module.exports);

api/livekit/token.js:
// Issues a LiveKit access token for the current member.
//
// Voice is members-only: the caller must hold a valid WorkOS AuthKit session.
// The token identity is derived server-side from the WorkOS user id, so a
// caller cannot choose their own room identity and cannot borrow another
// member's session to do so.
//
// Voice always requires a verified member session.

const withCors = require("../_cors");
const workos = require("../_workos");
const crypto = require("node:crypto");
const { AccessToken, AgentDispatchClient } = require("livekit-server-sdk");

function authRequired() {
  return true;
}

async function handler(req, res) {
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Use POST" });
  }

  if (!process.env.LIVEKIT_API_KEY || !process.env.LIVEKIT_API_SECRET || !process.env.LIVEKIT_URL) {
    return res.status(500).json({ error: "LiveKit is not configured" });
  }

  const requireAuth = authRequired();
  let memberUser = null;

  if (requireAuth) {
    // Fail closed. If auth is unconfigured or unreachable, refuse rather than
    // quietly handing out tokens to anonymous callers.
    if (!workos.isConfigured()) {
      console.error("livekit: AuthKit not configured; refusing to issue a token");
      return res.status(503).json({
        error: "Sign-in is not available right now.",
        code: "auth_unconfigured",
      });
    }

    memberUser = await workos.currentUser(req, res);

    if (!memberUser) {
      return res.status(401).json({
        error: "Sign in to talk live with Rachel.",
        code: "auth_required",
        loginUrl: `${workos.publicUrl()}/api/auth/login`,
      });
    }
  }

  try {
    const body = req.body || {};
    const room = "rachel-" + crypto.randomBytes(16).toString("hex");

    // Members get a stable, non-guessable identity derived server-side from
    // the WorkOS user id. Anonymous fallback keeps the old behaviour when the
    // gate is explicitly disabled via LIVEKIT_REQUIRE_AUTH=false.
    const identity = memberUser
      ? workos.memberIdentity(memberUser)
      : body.identity || `user-${Math.random().toString(36).slice(2, 12)}`;
    const name =
      body.name ||
      (memberUser
        ? [memberUser.firstName, memberUser.lastName].filter(Boolean).join(" ") ||
          memberUser.email ||
          "Member"
        : "Website visitor");

    const token = new AccessToken(
      process.env.LIVEKIT_API_KEY,
      process.env.LIVEKIT_API_SECRET,
      { identity, name, ttl: "10m" }
    );

    // The agent worker is registered in LiveKit Cloud, not in this repo, so its
    // name is configuration. Defaults to "rachel"; earlier code and commit
    // messages referenced "rachel-voice", so allow an override rather than
    // hardcoding a name that may not match the deployed worker.
    const agentName = process.env.LIVEKIT_AGENT_NAME || "rachel";

    token.addGrant({
      roomJoin: true,
      room,
      canPublish: true,
      canSubscribe: true,
      roomConfig: { agents: [{ agentName }] },
    });

    try {
      const host = process.env.LIVEKIT_URL.replace("wss://", "https://");
      const dispatch = new AgentDispatchClient(
        host,
        process.env.LIVEKIT_API_KEY,
        process.env.LIVEKIT_API_SECRET
      );
      await dispatch.createDispatch(room, agentName, { metadata: "web" });
    } catch (error) {
      // A dispatch failure is not fatal: the agent can still self-subscribe on
      // room creation. Surfaced in logs so a name mismatch is diagnosable.
      console.error("livekit: agent dispatch failed:", error && error.message);
    }

    return res.status(200).json({
      token: await token.toJwt(),
      url: process.env.LIVEKIT_URL,
      agent: agentName,
    });
  } catch (error) {
    console.error("LiveKit token error:", error);
    return res.status(500).json({ error: "Could not create LiveKit token" });
  }
}

module.exports = withCors(handler);

netlify/functions/api.js:
const routes = {
  'auth/login': require('../../api/auth/login'),
  'auth/logout': require('../../api/auth/logout'),
  'auth/callback': require('../../api/auth/callback'),
  'auth/status': require('../../api/auth/status'),
  'livekit/status': require('../../api/livekit/status'),
  'livekit/token': require('../../api/livekit/token'),
  chat: require('../../api/chat'),
  checkout: require('../../api/checkout'),
  health: require('../../api/health'),
  'stripe-pk': require('../../api/stripe-pk'),
  tts: require('../../api/tts'),
  'voice/tts': require('../../api/voice/tts'),
};

exports.handler = async event => {
  const path = event.path.replace(/^\/(?:\.netlify\/functions\/api|api)\/?/, '').replace(/\/$/, '');
  const route = routes[path];
  if (!route) return { statusCode: 404, body: JSON.stringify({ error: 'Not found' }) };
  let body = event.body || '';
  if (event.isBase64Encoded) body = Buffer.from(body, 'base64').toString('utf8');
  if (Buffer.byteLength(body) > 16384) return { statusCode: 413, body: '{"error":"Request too large"}' };
  const headers = Object.fromEntries(Object.entries(event.headers || {}).map(([k, v]) => [k.toLowerCase(), v]));
  if (body && headers['content-type']?.includes('application/json')) {
    try { body = JSON.parse(body); }
    catch { return { statusCode: 400, body: '{"error":"Invalid JSON"}' }; }
  }
  const req = { method: event.httpMethod, headers, body, query: event.queryStringParameters || {}, socket: {} };
  const response = { statusCode: 200, headers: { 'Cache-Control': 'no-store' }, body: '' };
  const res = {
    setHeader(key, value) { response.headers[key] = value; return this; },
    status(value) { response.statusCode = value; return this; },
    json(value) { this.setHeader('Content-Type', 'application/json'); response.body = JSON.stringify(value); return this; },
    send(value) { if (Buffer.isBuffer(value)) { response.body = value.toString('base64'); response.isBase64Encoded = true; } else response.body = String(value); return this; },
    end(value) { if (value !== undefined) this.send(value); return this; },
    redirect(status, location) { if (typeof status === 'string') { location = status; status = 302; } return this.status(status).setHeader('Location', location).end(); },
  };
  try { await route(req, res); }
  catch { res.status(500).json({ error: 'Service unavailable' }); }
  return response;
};

test/release.test.js:
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { handler } = require('../netlify/functions/api');
const call = (path, method = 'GET', body = '') => handler({ path: '/api/' + path, httpMethod: method, headers: { 'content-type': 'application/json', host: 'attacker.invalid' }, body });

test('voice stays closed even when legacy bypass is set', async () => {
  process.env.LIVEKIT_API_KEY = 'test'; process.env.LIVEKIT_API_SECRET = 'test';
  process.env.LIVEKIT_URL = 'wss://test.invalid'; process.env.LIVEKIT_REQUIRE_AUTH = 'false';
  delete process.env.WORKOS_API_KEY;
  const response = await call('livekit/token', 'POST', '{}');
  assert.equal(response.statusCode, 503);
  assert.equal(JSON.parse(response.body).code, 'auth_unconfigured');
  const status = JSON.parse((await call('livekit/status')).body);
  assert.equal(status.requiresAuth, true);
  assert.equal(status.authConfigured, false);
});
test('short cookie secret is never accepted as configured auth', () => {
  process.env.WORKOS_API_KEY = 'test'; process.env.WORKOS_CLIENT_ID = 'test';
  process.env.WORKOS_COOKIE_PASSWORD = 'short';
  assert.equal(require('../api/_workos').isConfigured(), false);
  delete process.env.WORKOS_API_KEY;
});
test('missing auth remains honest and does not redirect off-site', async () => {
  const response = await call('auth/login');
  assert.equal(response.statusCode, 503);
  assert.equal(JSON.parse(response.body).code, 'auth_unconfigured');
});
test('adapter rejects malformed, excessive and unknown requests', async () => {
  assert.equal((await call('chat', 'POST', '{')).statusCode, 400);
  assert.equal((await call('chat', 'POST', 'x'.repeat(17000))).statusCode, 413);
  assert.equal((await call('missing')).statusCode, 404);
});
test('checkout refuses unknown tiers and missing configuration', async () => {
  delete process.env.STRIPE_SECRET_KEY;
  assert.equal((await call('checkout', 'POST', '{"tier":"unknown"}')).statusCode, 400);
  assert.equal((await call('checkout', 'POST', '{"tier":"starter"}')).statusCode, 503);
});
